SELECT 'core-2026-09-v4','present-perfect-continuous','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"present-perfect-continuous","title":"Present perfect simple and continuous","level":"B2","order":31,"summary":"The perfect continuous connects an activity with now and draws attention to duration, repetition or visible evidence of recent effort. The activity may still continue or may have just stopped. The perfect simple often highlights a completed result or a number of finished items.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Focus on the activity","Keep both auxiliaries","Questions and negatives","State verbs and completed quantities"],"rules":[{"title":"Focus on the activity","explanation":"The perfect continuous connects an activity with now and draws attention to duration, repetition or visible evidence of recent effort. The activity may still continue or may have just stopped. The perfect simple often highlights a completed result or a number of finished items.","pattern":"Subject + **have been + -ing**","commonMistakes":["A continuous form does not guarantee that the activity is unfinished; context can show that it recently stopped."],"examples":["Use the present perfect continuous: She **has been preparing** the visitor guide for an hour so far today.","Use the present perfect continuous: She **has been restoring** the old portrait for an hour so far today."],"skill":"form"},{"title":"Keep both auxiliaries","explanation":"The construction has three verb parts: **have or has**, then **been**, then an **-ing** form. Only the first auxiliary changes with tense and subject. Been is the past participle of be; it connects perfect aspect with the continuous construction.","pattern":"She **has been working**.","commonMistakes":["Do not omit been or change it to being in this construction."],"examples":["Make a present-perfect-continuous negative: We **have not been preparing** the visitor guide all morning so far today.","Make a present-perfect-continuous negative: We **have not been restoring** the old portrait all morning so far today."],"skill":"meaning"},{"title":"Questions and negatives","explanation":"Move only **have or has** before the subject in questions. Put not after that same auxiliary in negatives. Been and the -ing form remain in place. A short answer repeats only the first auxiliary.","pattern":"Have they **been working**?","commonMistakes":["Have been they working? puts too much of the verb phrase before the subject."],"examples":["Complete the present-perfect-continuous question: Have they **been preparing** the visitor guide for long so far today?","Complete the present-perfect-continuous question: Have they **been restoring** the old portrait for long so far today?"],"skill":"contrast"},{"title":"State verbs and completed quantities","explanation":"Know, own and believe usually describe states and favour perfect simple: I have known her for years. A completed count also favours the simple: I have written three reports. Repeated activity can use continuous: I have been writing reports all morning. The meaning of the verb matters, not just a time expression.","pattern":"I have **known** her for years. / I have **been waiting** for an hour.","commonMistakes":["For and since can accompany simple perfect states; they do not automatically require continuous."],"examples":["Choose the present perfect SIMPLE, focusing on completion: I **have prepared** the visitor guide so far today.","Choose the present perfect SIMPLE, focusing on completion: I **have restored** the old portrait so far today."],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-perfect-continuous"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["The perfect continuous connects an activity with now and draws attention to duration, repetition or visible evidence of recent effort. The activity may still continue or may have just stopped. The perfect simple often highlights a completed result or a number of finished items.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Focus on the activity","explanation":"The perfect continuous connects an activity with now and draws attention to duration, repetition or visible evidence of recent effort. The activity may still continue or may have just stopped. The perfect simple often highlights a completed result or a number of finished items.","pattern":"Subject + **have been + -ing**","commonMistakes":["A continuous form does not guarantee that the activity is unfinished; context can show that it recently stopped."],"examples":["Use the present perfect continuous: She **has been preparing** the visitor guide for an hour so far today.","Use the present perfect continuous: She **has been restoring** the old portrait for an hour so far today."],"skill":"form","id":"present-perfect-continuous-foundation-1","domain":"verbs","referenceIds":["bc-perfect-continuous"],"readingVersion":"core-2026-09-v3"},{"title":"Keep both auxiliaries","explanation":"The construction has three verb parts: **have or has**, then **been**, then an **-ing** form. Only the first auxiliary changes with tense and subject. Been is the past participle of be; it connects perfect aspect with the continuous construction.","pattern":"She **has been working**.","commonMistakes":["Do not omit been or change it to being in this construction."],"examples":["Make a present-perfect-continuous negative: We **have not been preparing** the visitor guide all morning so far today.","Make a present-perfect-continuous negative: We **have not been restoring** the old portrait all morning so far today."],"skill":"meaning","id":"present-perfect-continuous-foundation-2","domain":"verbs","referenceIds":["bc-perfect-continuous"],"readingVersion":"core-2026-09-v3"},{"title":"Questions and negatives","explanation":"Move only **have or has** before the subject in questions. Put not after that same auxiliary in negatives. Been and the -ing form remain in place. A short answer repeats only the first auxiliary.","pattern":"Have they **been working**?","commonMistakes":["Have been they working? puts too much of the verb phrase before the subject."],"examples":["Complete the present-perfect-continuous question: Have they **been preparing** the visitor guide for long so far today?","Complete the present-perfect-continuous question: Have they **been restoring** the old portrait for long so far today?"],"skill":"contrast","id":"present-perfect-continuous-foundation-3","domain":"verbs","referenceIds":["bc-perfect-continuous"],"readingVersion":"core-2026-09-v3"},{"title":"State verbs and completed quantities","explanation":"Know, own and believe usually describe states and favour perfect simple: I have known her for years. A completed count also favours the simple: I have written three reports. Repeated activity can use continuous: I have been writing reports all morning. The meaning of the verb matters, not just a time expression.","pattern":"I have **known** her for years. / I have **been waiting** for an hour.","commonMistakes":["For and since can accompany simple perfect states; they do not automatically require continuous."],"examples":["Choose the present perfect SIMPLE, focusing on completion: I **have prepared** the visitor guide so far today.","Choose the present perfect SIMPLE, focusing on completion: I **have restored** the old portrait so far today."],"skill":"application","id":"present-perfect-continuous-foundation-4","domain":"verbs","referenceIds":["bc-perfect-continuous"],"readingVersion":"core-2026-09-v3"}],"recap":["Subject + **have been + -ing**","She **has been working**.","Have they **been working**?","I have **known** her for years. / I have **been waiting** for an hour."],"readingVersion":"core-2026-09-v4"},"stage":"3 · Time and experience","prerequisites":["stative-dynamic"],"readingReferenceIds":["bc-perfect-continuous"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='present-perfect-continuous'
